(825777, 93099, 6130, '<td valign="top">Lovely 10</td>', 'Lovely 10', '2004-07-26 09:14:25.000000', NULL, 1),
(825778, 93251, 2780, '<td valign="top">I''m not really sure how the photo matches the name of the band, but its still a nice shot. I think the boy on the left is a bit too close to the edge of the frame tho.</td>', 'I''m not really sure how the photo matches the name of the band, but its still a nice shot. I think the boy on the left is a bit too close to the edge of the frame tho.', '2004-07-26 09:14:54.000000', NULL, 1),
