(826903, 93569, 2, '<td valign="top">Very well done.  If you''ve had this subject waiting for the right challenge, you picked the right one! ;)</td>', 'Very well done.  If you''ve had this subject waiting for the right challenge, you picked the right one! ;)', '2004-07-27 00:18:21.000000', NULL, 1),
(826906, 92937, 2, '<td valign="top">The tones are really stunning in this photo.  I''m not crazy about the text.  I think the drop shadow''s a little heavy, and it''d be neat to have the text sit a little softer on the composition.  Wonderful job, though, overall.  Great band name, and the photo is definitely the highlight.  9.</td>', 'The tones are really stunning in this photo.  I''m not crazy about the text.  I think the drop shadow''s a little heavy, and it''d be neat to have the text sit a little softer on the composition.  Wonderful job, though, overall.  Great band name, and the photo is definitely the highlight.  9.', '2004-07-27 00:20:07.000000', NULL, 1),
(826908, 93237, 2, '<td valign="top">Simple and effective.  Nicely done.</td>', 'Simple and effective.  Nicely done.', '2004-07-27 00:21:17.000000', NULL, 1),
(826912, 93156, 2, '<td valign="top">Awesome picture.  I''m not a huge fan of the graphical layout, but I do like your color choices.  Overall nice job.</td>', 'Awesome picture.  I''m not a huge fan of the graphical layout, but I do like your color choices.  Overall nice job.', '2004-07-27 00:22:49.000000', NULL, 1),
(826914, 92706, 2, '<td valign="top">You''ve peaked my curiosity, and so job well done.  Wonderful composition.  Great, dark tones.</td>', 'You''ve peaked my curiosity, and so job well done.  Wonderful composition.  Great, dark tones.', '2004-07-27 00:24:09.000000', NULL, 1),
(826918, 93210, 2, '<td valign="top">I don''t know what a demerging personality conflict is, but this picture is awesome.</td>', 'I don''t know what a demerging personality conflict is, but this picture is awesome.', '2004-07-27 00:25:34.000000', NULL, 1),
(826921, 93603, 2, '<td valign="top">I''m a sucker for bright colors, but I really do like this one.  A really fun and entertaining composition, and a very believable band name.  Nice job!</td>', 'I''m a sucker for bright colors, but I really do like this one.  A really fun and entertaining composition, and a very believable band name.  Nice job!', '2004-07-27 00:28:01.000000', NULL, 1),
(826925, 93440, 2, '<td valign="top">I like the photo a lot, but the graphical editing seems overkill to me.  Even the photo by itself would have scored higher with me.</td>', 'I like the photo a lot, but the graphical editing seems overkill to me.  Even the photo by itself would have scored higher with me.', '2004-07-27 00:29:23.000000', NULL, 1),
(826928, 93444, 2, '<td valign="top">Well you don''t see that every day!  I''m not wild on your CD layout, but the picture''s definitely worth a double-take.</td>', 'Well you don''t see that every day!  I''m not wild on your CD layout, but the picture''s definitely worth a double-take.', '2004-07-27 00:30:51.000000', NULL, 1),
(826929, 93476, 2, '<td valign="top">I love the photo, but the text effect isn''t doing it for me.   It seems to really detract from the composition.</td>', 'I love the photo, but the text effect isn''t doing it for me.   It seems to really detract from the composition.', '2004-07-27 00:31:31.000000', NULL, 1),
(826931, 93553, 2, '<td valign="top">Great graphical editing.  I love the negative effect with "dpc" and the background.  Overall a great cover.  If I had to nitpick, I''d suggest a slightly lighter font -- I''m guessing that''s Arial, and it seems just a bit heavy to me personally.  8.</td>', 'Great graphical editing.  I love the negative effect with "dpc" and the background.  Overall a great cover.  If I had to nitpick, I''d suggest a slightly lighter font -- I''m guessing that''s Arial, and it seems just a bit heavy to me personally.  8.', '2004-07-27 00:33:02.000000', NULL, 1),
(826974, 93595, 12448, '<td valign="top">Hello theo.  Nice shot, interesting take on the challenge with the name.  But you can''t hide behind the knife, you have very distinct eyes.<br/> <br/>The light on the knife is a bit blown out and I''m not really sure I like the halo created by the light around the edges of the knife, it really doesn''t add to the shot for me.  I''m a basically peaceful person so this particular album cover wouldn''t appeal to me on an overal sense.  A 7</td>', 'Hello theo.  Nice shot, interesting take on the challenge with the name.  But you can''t hide behind the knife, you have very distinct eyes. The light on the knife is a bit blown out and I''m not really sure I like the halo created by the light around the edges of the knife, it really doesn''t add to the shot for me.  I''m a basically peaceful person so this particular album cover wouldn''t appeal to me on an overal sense.  A 7', '2004-07-27 01:21:28.000000', NULL, 1),
(826991, 92847, 12448, '<td valign="top">Annie? :)<br/> <br/>If not, it sure looks like a kitten I know named Annie!<br/> <br/>I love the look on her face, the crossed eyes, almost like a bug on her nose type look.  I like the capture overall but the coloration leaves my wanting.  The pink hue, while working with the title doesn''t blend well with the green background. for me.   Maybe if the background was desaturated just a bit.  Also the lettering is well done, good choice of font and nice size, but the angle is a bit wanting.  Maybe if it was cornered just a bit more instead of so horizontal.  As is a 6</td>', 'Annie? :) If not, it sure looks like a kitten I know named Annie! I love the look on her face, the crossed eyes, almost like a bug on her nose type look.  I like the capture overall but the coloration leaves my wanting.  The pink hue, while working with the title doesn''t blend well with the green background. for me.   Maybe if the background was desaturated just a bit.  Also the lettering is well done, good choice of font and nice size, but the angle is a bit wanting.  Maybe if it was cornered just a bit more instead of so horizontal.  As is a 6', '2004-07-27 01:53:32.000000', NULL, 1),
(826992, 93334, 12448, '<td valign="top">Ooooooooooooo, I love it, LOL!<br/> <br/>Good idea, good execution of the idea and the font and lettering is also well done.<br/> <br/>The picture is lacking a real wow or pop factor though.  It seems a bit bland.  And the smalle hand almost looks like a child''s hand, which bothers me for some odd reason, not a lot, but just a little.  Not enough to effect your score, but it''s there.<br/> <br/>As is a 7</td>', 'Ooooooooooooo, I love it, LOL! Good idea, good execution of the idea and the font and lettering is also well done. The picture is lacking a real wow or pop factor though.  It seems a bit bland.  And the smalle hand almost looks like a child''s hand, which bothers me for some odd reason, not a lot, but just a little.  Not enough to effect your score, but it''s there. As is a 7', '2004-07-27 01:55:50.000000', NULL, 1),
(826994, 93541, 12448, '<td valign="top">Man, that place is NO fun at all!<br/> <br/>Good take on the challenge but not sure how it would really play as an album cover.  The right side is overlit while the left is just about perfect.  A 7</td>', 'Man, that place is NO fun at all! Good take on the challenge but not sure how it would really play as an album cover.  The right side is overlit while the left is just about perfect.  A 7', '2004-07-27 01:56:50.000000', NULL, 1),
(826999, 93590, 24022, '<td valign="top">I LIKE IT!!!!!!</td>', 'I LIKE IT!!!!!!', '2004-07-27 02:02:14.000000', NULL, 1),
(827000, 93435, 15767, '<td valign="top">great shot of sunflowers - need different typeface and typeface color - difficult to read - placement of type could be better positioned also - really like the sunflowers</td>', 'great shot of sunflowers - need different typeface and typeface color - difficult to read - placement of type could be better positioned also - really like the sunflowers', '2004-07-27 02:03:23.000000', NULL, 1),
(827001, 93110, 15767, '<td valign="top">Great title - great hit song "Glazed Love" - creative</td>', 'Great title - great hit song "Glazed Love" - creative', '2004-07-27 02:05:08.000000', NULL, 1),
(827028, 93435, 7322, '<td valign="top">This was so well done! Right down to the choice of font. I love the wide angle for the field of sunflowers. I''m not nuts about the band name (partly because I don''t know what colligation is) but it is a masterful ''reproduction'' of a vintage album cover. Excellent.</td>', 'This was so well done! Right down to the choice of font. I love the wide angle for the field of sunflowers. I''m not nuts about the band name (partly because I don''t know what colligation is) but it is a masterful ''reproduction'' of a vintage album cover. Excellent.', '2004-07-27 02:17:34.000000', NULL, 1),
(827030, 93603, 7322, '<td valign="top">Cool cover. Don''t like the band name--it sounds more like an album title. But the cover is really well done and accurate to the style. Good job!</td>', 'Cool cover. Don''t like the band name--it sounds more like an album title. But the cover is really well done and accurate to the style. Good job!', '2004-07-27 02:18:26.000000', NULL, 1),
(827034, 92544, 7322, '<td valign="top">Should be "Dying". The font is kind of cheesy looking for authenticity. The photo works okay as album art but I don''t find it to be a great photo.</td>', 'Should be "Dying". The font is kind of cheesy looking for authenticity. The photo works okay as album art but I don''t find it to be a great photo.', '2004-07-27 02:20:14.000000', NULL, 1),
(827036, 92980, 7322, '<td valign="top">Very authentic looking. I know because this is excactly the type of CD or record I would pass right by while browsing. Not because it is bad art but because I know what type of musical style the art style typifies. Blah. Not to my taste at all. You''ve captured that style very well. Good choice of font and nice layout.</td>', 'Very authentic looking. I know because this is excactly the type of CD or record I would pass right by while browsing. Not because it is bad art but because I know what type of musical style the art style typifies. Blah. Not to my taste at all. You''ve captured that style very well. Good choice of font and nice layout.', '2004-07-27 02:23:05.000000', NULL, 1),
(827038, 93110, 7322, '<td valign="top">This is awesome! One of my favorites.</td>', 'This is awesome! One of my favorites.', '2004-07-27 02:25:44.000000', NULL, 1),
(827061, 93110, 20407, '<td valign="top">This is just perfect for the challenge. The font you''ve chosen is just right. I hope you get a ribbon for this :-) 9</td>', 'This is just perfect for the challenge. The font you''ve chosen is just right. I hope you get a ribbon for this :-) 9', '2004-07-27 02:51:11.000000', NULL, 1),
(827171, 93595, 20395, '<td valign="top">I like the emotion a lot, but the knife covering the nose strikes me funny somehow. Maybe if you had put it under one eye instead?</td>', 'I like the emotion a lot, but the knife covering the nose strikes me funny somehow. Maybe if you had put it under one eye instead?', '2004-07-27 04:58:38.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(827178, 92617, 4871, '<td valign="top">I really like the photograph, although personally I would have chosen a different font / color than what you have. It doesn''t blend with the photo. I would have used a white typeface - the font I don''t mind. Although this is a very subjective area and others may think it fantastic! Just my 2c worth :P</td>', 'I really like the photograph, although personally I would have chosen a different font / color than what you have. It doesn''t blend with the photo. I would have used a white typeface - the font I don''t mind. Although this is a very subjective area and others may think it fantastic! Just my 2c worth :P', '2004-07-27 05:13:45.000000', NULL, 1),
(827190, 92986, 20395, '<td valign="top">Eep! Ringu! I really like the colors, but something about the lighting makes the guitar look superimposed.</td>', 'Eep! Ringu! I really like the colors, but something about the lighting makes the guitar look superimposed.', '2004-07-27 06:07:41.000000', NULL, 1),
