INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(830120, 92846, 15810, '<td valign="top">Brilliant image, pity the text is a bit...."Word Art". The text looks stuck on without much thought of position or font..... so -1 for the text</td>', 'Brilliant image, pity the text is a bit...."Word Art". The text looks stuck on without much thought of position or font..... so -1 for the text', '2004-07-28 14:53:52.000000', NULL, 1),
(830125, 93542, 15810, '<td valign="top">You know, I can see this in the shops in the "easy listening section" I can imagine buying it for my Dad on Fathers Day coz I havent got a clue what else to buy....well done it really looks like a cover.</td>', 'You know, I can see this in the shops in the "easy listening section" I can imagine buying it for my Dad on Fathers Day coz I havent got a clue what else to buy....well done it really looks like a cover.', '2004-07-28 14:55:19.000000', NULL, 1),
(830129, 93334, 15810, '<td valign="top">Very Very clver, nice to see some thought and statement going into a submission.</td>', 'Very Very clver, nice to see some thought and statement going into a submission.', '2004-07-28 14:56:43.000000', NULL, 1),
(830134, 92760, 15810, '<td valign="top">Great image, love the curcature of the buildings...these boys look "In da hood" and I can really see this as an album cover.</td>', 'Great image, love the curcature of the buildings...these boys look "In da hood" and I can really see this as an album cover.', '2004-07-28 14:58:35.000000', NULL, 1),
(830136, 92563, 15810, '<td valign="top">Great idea well executed...well done.</td>', 'Great idea well executed...well done.', '2004-07-28 14:59:34.000000', NULL, 1),
(830141, 93502, 15810, '<td valign="top">Wow, stunning image.......I can imagine the album is rubbish but great cover anyhow.</td>', 'Wow, stunning image.......I can imagine the album is rubbish but great cover anyhow.', '2004-07-28 15:01:26.000000', NULL, 1),
(830145, 93421, 15810, '<td valign="top">OOOh I can imagine this album being TERRIBLE, but lovely image so well done.</td>', 'OOOh I can imagine this album being TERRIBLE, but lovely image so well done.', '2004-07-28 15:03:03.000000', NULL, 1),
(830173, 92965, 4007, '<td valign="top">The negative effect (or whatever it was) definately seems like a bad call here.  The colors don''t work well, the image is overly busy, your text is impossible to read at bottom left, and it''s nearly impossible to tell what this photo is actually of.</td>', 'The negative effect (or whatever it was) definately seems like a bad call here.  The colors don''t work well, the image is overly busy, your text is impossible to read at bottom left, and it''s nearly impossible to tell what this photo is actually of.', '2004-07-28 15:10:25.000000', NULL, 1),
(830185, 93470, 4007, '<td valign="top">The band name is a little bit of a stretch, but this shot actually has a quirky sort of feel and a crisp presentation that I could actually see as a real album cover.  Good work.</td>', 'The band name is a little bit of a stretch, but this shot actually has a quirky sort of feel and a crisp presentation that I could actually see as a real album cover.  Good work.', '2004-07-28 15:15:13.000000', NULL, 1),
(830192, 92980, 10858, '<td valign="top">I love the colours, composition, really moody shot! :-) Though, I am not familiar with the tipography in the left bottom corner. It''s so different from the one above (I like that), and the whites are adding too much Contrast IMHO. I would use a smaller font type for the text in the bottom and align it absolutely to the right, I would also use the beige shades instead of the white. Just an idea. (7)</td>', 'I love the colours, composition, really moody shot! :-) Though, I am not familiar with the tipography in the left bottom corner. It''s so different from the one above (I like that), and the whites are adding too much Contrast IMHO. I would use a smaller font type for the text in the bottom and align it absolutely to the right, I would also use the beige shades instead of the white. Just an idea. (7)', '2004-07-28 15:18:44.000000', NULL, 1),
(830197, 93155, 4007, '<td valign="top">I really like the band name.  The photo is adequate but somewhat dull.</td>', 'I really like the band name.  The photo is adequate but somewhat dull.', '2004-07-28 15:20:47.000000', NULL, 1),
(830253, 93444, 22689, '<td valign="top">So great ! I like it so much !</td>', 'So great ! I like it so much !', '2004-07-28 15:54:30.000000', NULL, 1),
(830291, 93335, 16151, '<td valign="top">Caribou...that is a deer :P</td>', 'Caribou...that is a deer :P', '2004-07-28 16:23:34.000000', NULL, 1),
(830294, 92723, 16151, '<td valign="top">Your cherries look a bit like apples :P</td>', 'Your cherries look a bit like apples :P', '2004-07-28 16:24:39.000000', NULL, 1),
(830309, 93472, 10858, '<td valign="top">Cool! Tasty composition, matching fonts, and it''s funny! :-)) Good luck, go for a ribbon! (10)</td>', 'Cool! Tasty composition, matching fonts, and it''s funny! :-)) Good luck, go for a ribbon! (10)', '2004-07-28 16:37:10.000000', NULL, 1),
(830409, 93237, 23251, '<td valign="top">Sorry but this photo didn''t do or say anything to me. The motion blur to the left of a striped flag dosen''t seem to work.</td>', 'Sorry but this photo didn''t do or say anything to me. The motion blur to the left of a striped flag dosen''t seem to work.', '2004-07-28 17:24:24.000000', NULL, 1),
(830424, 93541, 23251, '<td valign="top">While the idea is ok, it it has a few floors in the photo.  It needs to be straighted more! I can see that you have tried and now there is a gap on the bottom right hand side that should have been cropped.  The hard shadow could have been softened if you had used fill flash.  Nice sky, nice colour and well framed.</td>', 'While the idea is ok, it it has a few floors in the photo.  It needs to be straighted more! I can see that you have tried and now there is a gap on the bottom right hand side that should have been cropped.  The hard shadow could have been softened if you had used fill flash.  Nice sky, nice colour and well framed.', '2004-07-28 17:30:35.000000', NULL, 1),
(830442, 93558, 23251, '<td valign="top">I think because the cacti take up so large a part of the frame that they don''t indicate Diminutive and also take a lot away from the image.  The sky is lovely with the sun behind the cacti but most of it is hidden. Because some of the detail is showing on the cacti it has made that part into a dark area if you were to darken it more it would become a silhouette instead of being somewhere in between.</td>', 'I think because the cacti take up so large a part of the frame that they don''t indicate Diminutive and also take a lot away from the image.  The sky is lovely with the sun behind the cacti but most of it is hidden. Because some of the detail is showing on the cacti it has made that part into a dark area if you were to darken it more it would become a silhouette instead of being somewhere in between.', '2004-07-28 17:40:20.000000', NULL, 1),
(830449, 93177, 23251, '<td valign="top">Although the photo is Ok. The large black area at the top takes a lot away for me.</td>', 'Although the photo is Ok. The large black area at the top takes a lot away for me.', '2004-07-28 17:45:51.000000', NULL, 1),
(830453, 92965, 23251, '<td valign="top">Sorry this photo is so busy that nothing really stands out or attracts your attention.  Its impossible to read the writing as well.</td>', 'Sorry this photo is so busy that nothing really stands out or attracts your attention.  Its impossible to read the writing as well.', '2004-07-28 17:48:17.000000', NULL, 1),
(830472, 93443, 23251, '<td valign="top">Nice feel to the photo there are a few things that takes a bit away. The placement of the text and the large blank area at the bottom also the lady in the middle must have moved as she is OOF where the other lady is not!</td>', 'Nice feel to the photo there are a few things that takes a bit away. The placement of the text and the large blank area at the bottom also the lady in the middle must have moved as she is OOF where the other lady is not!', '2004-07-28 17:55:04.000000', NULL, 1),
(830495, 93541, 509, '<td valign="top">I like the subject, but the composition doesn''t quite work for me.  It seems a little tight on the left and right sides.  Some fill flash might have been able to clear up the shadows in the center as well.  The colors and sky are great though.</td>', 'I like the subject, but the composition doesn''t quite work for me.  It seems a little tight on the left and right sides.  Some fill flash might have been able to clear up the shadows in the center as well.  The colors and sky are great though.', '2004-07-28 18:11:09.000000', NULL, 1),
(830498, 93558, 509, '<td valign="top">I think this might work better with either more or less of a silhouette.  The problem is that I am drawn to the red tops of the cacti, but there isn''t enough detail there.  I think in this case, I would prefer less of a silhouette, rather than more.  Fill flash (if you are able to use a high enough shutter speed) might work.  Otherwise I like the composition and background.  I could see this as a country album cover, but probably not with the band name ; )</td>', 'I think this might work better with either more or less of a silhouette.  The problem is that I am drawn to the red tops of the cacti, but there isn''t enough detail there.  I think in this case, I would prefer less of a silhouette, rather than more.  Fill flash (if you are able to use a high enough shutter speed) might work.  Otherwise I like the composition and background.  I could see this as a country album cover, but probably not with the band name ; )', '2004-07-28 18:13:34.000000', NULL, 1),
(830501, 93410, 509, '<td valign="top">Great macro, what is the surface he''s on?  It almost looks like a pan-shot, and I like the effect it gives.</td>', 'Great macro, what is the surface he''s on?  It almost looks like a pan-shot, and I like the effect it gives.', '2004-07-28 18:14:15.000000', NULL, 1),
(830504, 93315, 509, '<td valign="top">I don''t mind the shallow depth of field, but imho am not sure it works well with the high contrast objects (the jack at the bottom and the bridge on the left).  A different crop might solve this.</td>', 'I don''t mind the shallow depth of field, but imho am not sure it works well with the high contrast objects (the jack at the bottom and the bridge on the left).  A different crop might solve this.', '2004-07-28 18:15:58.000000', NULL, 1),
(830506, 92245, 509, '<td valign="top">The darkness of the image is ok, but I think boosting the brightness of the eyes might really give a nice, eerie look to this.</td>', 'The darkness of the image is ok, but I think boosting the brightness of the eyes might really give a nice, eerie look to this.', '2004-07-28 18:16:51.000000', NULL, 1),
(830508, 93472, 509, '<td valign="top">A little busy at the bottom of the shot imho.  That said, the lighting used and focus is great.</td>', 'A little busy at the bottom of the shot imho.  That said, the lighting used and focus is great.', '2004-07-28 18:17:52.000000', NULL, 1),
(830510, 93568, 509, '<td valign="top">I really like the background used.  Some dodging might help bring out the insect a bit more.  Nice work.</td>', 'I really like the background used.  Some dodging might help bring out the insect a bit more.  Nice work.', '2004-07-28 18:18:54.000000', NULL, 1),
(830514, 92724, 509, '<td valign="top">Not quite contrasty enough for an album cover (imho).  However, I like the colors of the clouds, and catching that rainbow - very well done.  I think that something could be done to the water to give it more "pop", but I''m not sure what..</td>', 'Not quite contrasty enough for an album cover (imho).  However, I like the colors of the clouds, and catching that rainbow - very well done.  I think that something could be done to the water to give it more "pop", but I''m not sure what..', '2004-07-28 18:20:04.000000', NULL, 1),
(830615, 93099, 20410, '<td valign="top">Society lol. Nice image, Well processed</td>', 'Society lol. Nice image, Well processed', '2004-07-28 19:29:33.000000', NULL, 1),
(830617, 93588, 20410, '<td valign="top">Made me jump...</td>', 'Made me jump...', '2004-07-28 19:31:34.000000', NULL, 1),
(830620, 93127, 20410, '<td valign="top">This is the greatest image EVER. I would buy a copy of this if you made a print available. When I buy it I''d donate it to an old store near my house called the Purple Cow, Great choclateers. So if you do make a print available, put your name in the corner for all to see who comes into the purple cow.... didn''t sound right.... 9!</td>', 'This is the greatest image EVER. I would buy a copy of this if you made a print available. When I buy it I''d donate it to an old store near my house called the Purple Cow, Great choclateers. So if you do make a print available, put your name in the corner for all to see who comes into the purple cow.... didn''t sound right.... 9!', '2004-07-28 19:33:17.000000', NULL, 1),
(830624, 93558, 20410, '<td valign="top">hehehe Nice! 7!</td>', 'hehehe Nice! 7!', '2004-07-28 19:34:27.000000', NULL, 1),
