(833610, 93468, 8054, '<td valign="top">This group name sounds like a deli sandwich. Maybe it because it''s almost lunch time. Hmm. Excellent and creative! My only issue is the sky. It has lots of compression artifacts or maybe it''s just noise. Otherwise, great job! 9</td>', 'This group name sounds like a deli sandwich. Maybe it because it''s almost lunch time. Hmm. Excellent and creative! My only issue is the sky. It has lots of compression artifacts or maybe it''s just noise. Otherwise, great job! 9', '2004-07-30 15:42:54.000000', NULL, 1),
(833627, 92563, 3697, '<td valign="top">I like the name, and I particularly like how your picture directly relates to that name. Very nice work.</td>', 'I like the name, and I particularly like how your picture directly relates to that name. Very nice work.', '2004-07-30 16:01:38.000000', NULL, 1),
(833637, 93603, 8054, '<td valign="top">Hands down my favorite of the bunch! Love the background and the typeface choices are perfect. I think that the glow you gave was a bit thick but perfect other than that. I give it a 9.5 but I need to round up to a 10 (too bad, huh?). :)</td>', 'Hands down my favorite of the bunch! Love the background and the typeface choices are perfect. I think that the glow you gave was a bit thick but perfect other than that. I give it a 9.5 but I need to round up to a 10 (too bad, huh?). :)', '2004-07-30 16:12:27.000000', NULL, 1),
(833638, 93210, 8054, '<td valign="top">This is another favorite of mine. Love the photo in b/w. It has very nice tonal range and contrast. The eyes Are a very strong focal point and they show lots of emotion. 10</td>', 'This is another favorite of mine. Love the photo in b/w. It has very nice tonal range and contrast. The eyes Are a very strong focal point and they show lots of emotion. 10', '2004-07-30 16:15:17.000000', NULL, 1),
(833662, 93585, 8054, '<td valign="top">This is just very wrong and gross. But from a creative standpoint I love it. Dead bugs and band name contrasting literally/visually is a nice touch. Lighting seems a bit off and even bright in some areas like the right side bugs. 7</td>', 'This is just very wrong and gross. But from a creative standpoint I love it. Dead bugs and band name contrasting literally/visually is a nice touch. Lighting seems a bit off and even bright in some areas like the right side bugs. 7', '2004-07-30 16:43:25.000000', NULL, 1),
(833667, 93021, 2310, '<td valign="top">I think this shot is great...I just wish that the lettering wasn''t covering up the lip of the bottle.  The distortion just under the bottle is also a little distracting.</td>', 'I think this shot is great...I just wish that the lettering wasn''t covering up the lip of the bottle.  The distortion just under the bottle is also a little distracting.', '2004-07-30 16:46:59.000000', NULL, 1),
