(835630, 93208, 22734, '<td valign="top">This is possibly the most striking visual in this collection. I expect this image to end up at the top and so bumping it to 9</td>', 'This is possibly the most striking visual in this collection. I expect this image to end up at the top and so bumping it to 9', '2004-08-01 19:16:37.000000', NULL, 1),
(835631, 92861, 22734, '<td valign="top">This is a winner. The title and the face take the show. Returning to bump this image to 8.</td>', 'This is a winner. The title and the face take the show. Returning to bump this image to 8.', '2004-08-01 19:17:26.000000', NULL, 1),
