(835634, 93437, 22734, '<td valign="top">A dangerous font but comp and name great. Bumping you to 7</td>', 'A dangerous font but comp and name great. Bumping you to 7', '2004-08-01 19:18:48.000000', NULL, 1),
(835637, 93541, 489, '<td valign="top">I like it, catchy title - I think it would have been even better with the full name in type on the image, but a great find nonetheless!</td>', 'I like it, catchy title - I think it would have been even better with the full name in type on the image, but a great find nonetheless!', '2004-08-01 19:19:36.000000', NULL, 1),
(835638, 93110, 22734, '<td valign="top">A wild reach with the title but a cute and tidy look which evokes laughter. Returning to bump this image to 8</td>', 'A wild reach with the title but a cute and tidy look which evokes laughter. Returning to bump this image to 8', '2004-08-01 19:19:37.000000', NULL, 1),
