(835641, 92894, 489, '<td valign="top">Interesting composition, and nice simple type work. I like it.</td>', 'Interesting composition, and nice simple type work. I like it.', '2004-08-01 19:20:32.000000', NULL, 1),
(835642, 93504, 1031, '<td valign="top">Just saw a great show about researching the Mitchell Standard -- not the porn fare --  the cameras used to shoot (among zillions of others) the original King Kong.</td>', 'Just saw a great show about researching the Mitchell Standard -- not the porn fare --  the cameras used to shoot (among zillions of others) the original King Kong.', '2004-08-01 19:20:40.000000', NULL, 1),
(835643, 93526, 489, '<td valign="top">I love the hit single part...Good fun cover.</td>', 'I love the hit single part...Good fun cover.', '2004-08-01 19:21:03.000000', NULL, 1),
(835644, 93303, 489, '<td valign="top">LOl... I cracked up when this one popped up. I love the etching in the drain, nice touch!</td>', 'LOl... I cracked up when this one popped up. I love the etching in the drain, nice touch!', '2004-08-01 19:21:57.000000', NULL, 1),
(835646, 93598, 489, '<td valign="top">Cool strobe effect. Works very well here.</td>', 'Cool strobe effect. Works very well here.', '2004-08-01 19:22:22.000000', NULL, 1),
(835647, 93521, 22734, '<td valign="top">Not happy with your type selection, but you got such a nice shot whith that eye looking at the viewer that you get bumped to 7</td>', 'Not happy with your type selection, but you got such a nice shot whith that eye looking at the viewer that you get bumped to 7', '2004-08-01 19:22:23.000000', NULL, 1),
(835649, 93594, 1031, '<td valign="top">The water is a great touch. I always have trouble with black type on red, so I''d like it a touch heavier for readability, but it works OK.</td>', 'The water is a great touch. I always have trouble with black type on red, so I''d like it a touch heavier for readability, but it works OK.', '2004-08-01 19:23:07.000000', NULL, 1),
