(835655, 93459, 1031, '<td valign="top">Not to mention the Triple-A club ... Andrew, Abraham, and Alexander (killed by the Double-A, Aaron).</td>', 'Not to mention the Triple-A club ... Andrew, Abraham, and Alexander (killed by the Double-A, Aaron).', '2004-08-01 19:27:17.000000', NULL, 1),
(835656, 93610, 489, '<td valign="top">Nicley done - I love the colors; the reds and golds are excellent together. Good job with the type as well.</td>', 'Nicley done - I love the colors; the reds and golds are excellent together. Good job with the type as well.', '2004-08-01 19:27:59.000000', NULL, 1),
(835660, 93558, 489, '<td valign="top">Fill flash here, just a light amount, would have really brought this up a notch I think. The sky is beautiful.</td>', 'Fill flash here, just a light amount, would have really brought this up a notch I think. The sky is beautiful.', '2004-08-01 19:30:08.000000', NULL, 1),
(835662, 93110, 489, '<td valign="top">I can''t stop laughing at this one - great shot and great type work. Good luck!</td>', 'I can''t stop laughing at this one - great shot and great type work. Good luck!', '2004-08-01 19:30:58.000000', NULL, 1),
(835663, 93155, 489, '<td valign="top">That''s really not a bad name at all - Distant Ports Calling...I like that. The shot is terrific,  it would have walked away with the "Blue" challenge I think, and gets high marks here as well. Well done.</td>', 'That''s really not a bad name at all - Distant Ports Calling...I like that. The shot is terrific,  it would have walked away with the "Blue" challenge I think, and gets high marks here as well. Well done.', '2004-08-01 19:32:31.000000', NULL, 1),
(835665, 92706, 489, '<td valign="top">I like the urban monochrome shot - looks terrific.</td>', 'I like the urban monochrome shot - looks terrific.', '2004-08-01 19:34:00.000000', NULL, 1),
(835666, 92915, 489, '<td valign="top">Hard to imagine as a band name, but boy do I love the shot. Great focus and soft colors.</td>', 'Hard to imagine as a band name, but boy do I love the shot. Great focus and soft colors.', '2004-08-01 19:35:39.000000', NULL, 1),
(835668, 93334, 1031, '<td valign="top">Not gonna let the Brits off, eh? Woud make a good editorial cartoon too.</td>', 'Not gonna let the Brits off, eh? Woud make a good editorial cartoon too.', '2004-08-01 19:38:30.000000', NULL, 1),
(835669, 93156, 489, '<td valign="top">Lol...man this is great. I love the title, and I really love the shot. Very clean, very crisp, and the little crickets washing down the tequila are priceless. Good luck!</td>', 'Lol...man this is great. I love the title, and I really love the shot. Very clean, very crisp, and the little crickets washing down the tequila are priceless. Good luck!', '2004-08-01 19:38:35.000000', NULL, 1),
